const usageHistory = (hours) => {
  const n = Math.max(1, Math.min(720, Number(hours) || 24));
  const points = [];
  // One snapshot every 30 minutes for ≤ 48h, hourly beyond, ending now.
  const stepMs = n <= 48 ? 30 * MIN : HOUR;
  const count = Math.floor((n * HOUR) / stepMs);
  for (let i = count; i >= 0; i--) {
    const t = NOW - i * stepMs;
    const phase = (count - i) / Math.max(1, count);
    const sessionPct = Math.round(Math.max(0, 40 * Math.abs(Math.sin(phase * 9.4)) * (1 - phase * 0.6) + 6 * phase) * 10) / 10;
    const weeklyPct = Math.round((12 + 34 * phase) * 10) / 10;
    points.push({
      sessionPct,
      weeklyPct,
      weeklyOpusPct: Math.round((3 + 9 * phase) * 10) / 10,
      weeklySonnetPct: null,
      createdAt: new Date(t).toISOString(),
    });
  }
  return points;
};

