// ─── Pre-rename aliases ───────────────────────────────────────────────────
// Batch 3 renamed seven web-only procedures. The before/after runs share this
// module, so without these the *old* build asks for a name the fixtures no
// longer answer, renders its error state, and the diff reports the resulting
// change in axe findings as a regression. Both spellings answer.
for (const [was, now] of [
  ["project.instanceInfo", "project.claudeInfo"],
  ["project.containerStats", "project.workerStats"],
  ["project.deleteClaudeSession", "project.deleteConversation"],
  ["claudeAccount.allSessions", "claudeAccount.conversations"],
  ["claudeAccount.archiveSession", "claudeAccount.archiveConversation"],
  ["claudeAccount.deleteSession", "claudeAccount.deleteConversation"],
  ["claudeAccount.deleteSessions", "claudeAccount.deleteConversations"],
]) {
  if (procedures[now] && !procedures[was]) procedures[was] = procedures[now];
  if (empty[now] && !empty[was]) empty[was] = empty[now];
}

// ─── The API, as one transport-agnostic function ──────────────────────────
//
// `makeApi` used to live in `shoot.mjs`, where it could only be spoken to
// through a Playwright `Route`. That is why the behavioural tests could not
// reuse it and why the audit could photograph a page state no unit test had
// ever asserted. It answers a plain `{method, url, body}` and returns a plain
// `{status, contentType, body}` — Playwright's `route.fulfill` shape, and
// equally a `Response` in jsdom.
//
// Scenarios: `default` (logged in, rich data), `empty` (first run), `slow`
// (every query hangs), `fail` (every query 500s), `anon` (no session).
// `failOnly` / `hangOnly` break a named set of procedures and leave the rest
// working — the blanket scenarios cannot reach a tab's own states, because
// `project.getBySlug` breaks with everything else and the page never renders
// its tabs at all.

const TRPC_CODES = { NOT_FOUND: 404, FORBIDDEN: 403, UNAUTHORIZED: 401, BAD_REQUEST: 400 };

const json = (status, body) => ({ status, contentType: "application/json", body: JSON.stringify(body) });

/**
 * @param {string} scenario
 * @param {Record<string, Function>} overrides  per-procedure replacements
 * @param {{failOnly?: string[], hangOnly?: string[], missing?: Set<string>, stateful?: boolean}} only
 */
export function makeApi(scenario = "default", overrides = {}, only = {}) {
  const failOnly = new Set(only.failOnly ?? []);
  const hangOnly = new Set(only.hangOnly ?? []);
  const missing = only.missing instanceof Set ? only.missing : new Set();
  const store = only.stateful ? mutableProjects() : null;
  const procs = {
    ...procedures,
    ...(scenario === "empty" ? empty : {}),
    ...(store ? store.procedures : {}),
    ...overrides,
  };

  function callOne(name, input) {
    const fn = procs[name];
    if (scenario === "fail" || failOnly.has(name) || failing.has(name)) {
      return { error: { json: { message: `Simulated failure in ${name}`, code: -32603, data: { code: "INTERNAL_SERVER_ERROR", httpStatus: 500, path: name } } } };
    }
    if (!fn) {
      missing.add(name);
      return { error: { json: { message: `No fixture for ${name}`, code: -32603, data: { code: "INTERNAL_SERVER_ERROR", httpStatus: 500, path: name } } } };
    }
    try {
      const data = fn(input);
      return { result: { data: { json: data === undefined ? null : data } } };
    } catch (e) {
      // A fixture that throws with a tRPC code means that code, not a 500:
      // "Project not found" and "the server broke" are different states and
      // the page renders them differently.
      const code = e.code && TRPC_CODES[e.code] ? e.code : "INTERNAL_SERVER_ERROR";
      if (code === "INTERNAL_SERVER_ERROR") missing.add(`${name} (threw: ${e.message})`);
      return { error: { json: { message: String(e.message), code: -32603, data: { code, httpStatus: TRPC_CODES[code] ?? 500, path: name } } } };
    }
  }

  return {
    session: scenario === "anon" ? null : session,
    missing,
    store,
    /**
     * @param {{method?: string, url: string, body?: string|null}} req
     * @returns {{status:number, contentType:string, body:string}|{hang:true}}
     *   `hang` is a request that never answers — the caller decides whether
     *   that is a 15s sleep (a shot) or a promise that never settles (jsdom).
     */
    respond({ method = "GET", url, body = null }) {
      const u = new URL(url, "http://127.0.0.1");
      const path = u.pathname;
      if (scenario === "slow" && path.startsWith("/api/trpc")) return { hang: true };
      if (path === "/api/auth/get-session") return json(200, this.session);
      if (path.startsWith("/api/auth/") && !rest[`${method} ${path}`]) return json(200, {});
      if (path === "/api/events") return { status: 200, contentType: "text/event-stream", body: ": ok\n\n" };
      if (path === "/api/health") return json(200, { ok: true, buildId: "audit" });

      if (path.startsWith("/api/trpc/")) {
        const names = decodeURIComponent(path.slice("/api/trpc/".length)).split(",");
        if (names.some((n) => hangOnly.has(n))) return { hang: true };
        let inputs = {};
        try {
          inputs = method === "GET" ? JSON.parse(u.searchParams.get("input") ?? "{}") : JSON.parse(body ?? "{}");
        } catch {}
        const isBatch = u.searchParams.get("batch") === "1";
        const results = names.map((name, i) => {
          const raw = isBatch ? inputs[String(i)] : inputs;
          const input = raw && typeof raw === "object" && "json" in raw ? raw.json : raw;
          return callOne(name, input);
        });
        return json(200, isBatch ? results : results[0]);
      }

      const key = `${method} ${path}`;
      let restFn = rest[key] ?? rest[path];
      if (!restFn) {
        for (const [k, fn] of Object.entries(rest)) {
          const [m, pat] = k.split(" ");
          if (m !== method) continue;
          const a = pat.split("/"), b = path.split("/");
          if (a.length === b.length && a.every((seg, i) => seg.startsWith(":") || seg === b[i])) { restFn = fn; break; }
        }
      }
      if (restFn) {
        const out = restFn({});
        if (out && out.__sse) return { status: 200, contentType: "text/event-stream", body: out.body };
        return json(200, out);
      }
      missing.add(key);
      return json(404, {});
    },
  };
}

// ─── A writable project list, for a journey that creates and deletes ──────
//
// The read fixtures are constants: `project.create` answers with a plausible
// row and forgets it, so a test that creates a project and then looks for it
// gets a 404 and passes for the wrong reason — the page would have shown
// "not found" either way. `stateful: true` layers a mutable copy over the
// rows for the five procedures a create/edit/delete journey touches. Off by
// default, so the shot harness keeps photographing identical data every run.
function mutableProjects() {
  const rows = projectRows.map((p) => ({ ...p }));
  const bySlug = (slug) => rows.find((p) => p.slug === slug) ?? null;
  const byId = (id) => rows.find((p) => p.id === id) ?? null;
  const slugify = (name) => String(name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "project";
  const item = (p) => ({
    ...p,
    container: containersBySlug[p.slug] ?? null,
    claudeAccount: accountInclude(p.claudeAccountId),
    exposedServices: exposedServiceRows.filter((s) => s.projectId === p.id),
  });
  return {
    rows,
    procedures: {
      "project.list": () => rows.map(item),
      "project.getBySlug": (input) => {
        const p = bySlug(input?.slug);
        if (!p) notFound();
        const dt = deployTargets.find((t) => t.id === p.deployTargetId);
        return {
          ...item(p),
          mcpServers: mcpRows.filter((m) => m.projectId === p.id),
          deployTarget: dt ? { id: dt.id, name: dt.name } : null,
          hasGithubPat: false,
          claudeAccount: accountInclude(p.claudeAccountId),
        };
      },
      "project.create": (input = {}) => {
        const row = {
          ...projectDefaults,
          ...input,
          id: `prj_new_${rows.length}_01J8Q4XXXXXXXXXXXXXXXXXX`,
          name: input.name ?? "New project",
          slug: input.slug ?? slugify(input.name ?? "New project"),
          status: "STOPPED",
          createdAt: new Date(NOW).toISOString(),
          updatedAt: new Date(NOW).toISOString(),
        };
        rows.push(row);
        return row;
      },
      "project.update": (input = {}) => {
        const p = byId(input.id);
        if (!p) notFound();
        const { id, ...data } = input;
        const changed = Object.keys(data).filter((k) => JSON.stringify(data[k] ?? null) !== JSON.stringify(p[k] ?? null));
        Object.assign(p, data, { updatedAt: new Date(NOW).toISOString() });
        return { ...p, restartRequired: false, rcRestarted: false, changedFields: changed };
      },
      "project.delete": (input = {}) => {
        const i = rows.findIndex((p) => p.id === input.id);
        if (i < 0) notFound();
        return rows.splice(i, 1)[0];
      },
    },
  };
}
